mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T4.ASSET_TYPE1 assetType1, T2.PORTFOLIO_NAME portfolioName, T1.PRICE*100 price, T4.TERM_TYPE termType, T4.TERM_DAYS repoTerm, T4.BUSI_PS ps, T1.ENTRUST_AMT entrustAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.PRICE_MODEL priceModel, IFNULL(T5.FINISH_AMT,0) finishAmt, round(IFNULL(T5.FINISH_AMT,0)/T1.ENTRUST_AMT,4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(IFNULL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND T4.ASSET_TYPE1 = #{assetType1}
AND T4.TERM_TYPE = #{termType}
AND T1.CCY = #{ccy}
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.PRICE_MODEL = #{priceModel}
AND T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N})
order by T1.ENTRUST_ID DESC
